<script lang="ts">
	// @ts-expect-error — generated by Wails
	import { GetLanguages, GetSelectedLanguage, SetSelectedLanguage } from '@wails/go/gui/App.js';
	// @ts-expect-error — generated by Wails
	import { LogError } from '@wails/runtime/runtime';
	import Button from '$components/Button.svelte';
	import PageLayout from '$components/PageLayout.svelte';
	import { pageValid } from '$lib/state.svelte';

	interface Language {
		code: string;
		name: string;
		locale: string;
	}

	let languages = $state<Language[]>([]);
	let selectedCode = $state<string>('');
	let loading = $state(true);

	async function loadLanguages(): Promise<void> {
		if (languages.length > 0) {
			const saved = await GetSelectedLanguage();
			if (saved && languages.some(l => l.code === saved)) {
				selectedCode = saved;
			}
			loading = false;
			return;
		}
		try {
			languages = await GetLanguages();
			const saved = await GetSelectedLanguage();
			if (saved && languages.some(l => l.code === saved)) {
				selectedCode = saved;
			} else if (languages.length > 0) {
				selectedCode = languages[0].code;
				await SetSelectedLanguage(selectedCode);
			}
		} catch (err) {
			LogError(`Failed to load languages: ${err}`);
		} finally {
			loading = false;
		}
	}

	async function selectLanguage(code: string): Promise<void> {
		selectedCode = code;
		try {
			await SetSelectedLanguage(code);
		} catch (err) {
			LogError(`Failed to set language: ${err}`);
		}
	}

	// Update pageValid based on language selection
	$effect(() => {
		pageValid.value = !!selectedCode;
	});

	loadLanguages();
</script>

<PageLayout title="Welcome to AestheticOS">
	<div class="welcome-content">
		<p class="subtitle">This installer will guide you through setting up your system.</p>

		{#if loading}
			<span class="loading-text">Loading...</span>
		{:else}
			<ul class="language-list">
				{#each languages as lang (lang.code)}
					<li>
						<button
							type="button"
							class={['lang-item', { 'lang-item--selected': lang.code === selectedCode }]}
							onclick={() => selectLanguage(lang.code)}
						>
							{lang.name}
						</button>
					</li>
				{/each}
			</ul>
		{/if}
	</div>
</PageLayout>

